    cnt=collections.Counter(c for r in gi for c in r)
    nz=[c for c in cnt if c!=0]
    # ring = color with larger bbox; inner = other
    info={}
    for c in nz:
        pts=[(a,b) for a in range(H) for b in range(W) if gi[a][b]==c]
        info[c]=(min(a for a,_ in pts),max(a for a,_ in pts),min(b for _,b in pts),max(b for _,b in pts))
    ring=max(info,key=lambda k:info[k][2]-info[k][1]+info[k][3]-info[k][4]+1)  # biggest bbox area? use perimeter-ish
    inn=[k for k in nz if k!=ring][0]
    r0,r1,r2,r3=info[ring]; i0,i1,i2,i3=info[inn]
    rh=r1-r0+1; rw=r3-r2+1; sh=i1-i0+1; sw=i3-i2+1
    p=min(sh, rw if False else 0, None)
    # pad = min(inner side, floor(ring side / inner side)) — use max side of each
    rm=max(rh,rw); sm=max(sh,sw)
    p=min(sm, rm//sm) if sm else 0
    o=[r for r in range(H) for c_ in range(W) if g_i:=gi[r][c_] for g_i in [0]] if False else None
    out=[row[:] for row in gi]
    for a in range(r0-p, r1+p+1):
        for b in range(r2-p, r3+p+1):
            if not (r0<=a<=r1 and r2<=b<=r3) or gi[a][b]!=ring:
                out[a][b]=inn
    # redraw ring over fill
    for a in range(r0,r1+1):
        for b in range(r2,r3+1):
            if gi[a][b]==ring: out[a][b]=ring
    return out

